import { useQuery } from '@tanstack/react-query'
import claimApi from '../../axios/claim'
import agencyApi from '../../axios/agency'
import { assertApiOk } from '../assertApiOk'

export const BENEFITS_LIST_KEY = 'benefits-list'
export const QUESTIONNAIRE_KEY = 'questionnaire-list'

export const useBenefitsListQuery = ({
  packageCode,
  product,
  partner,
  insuranceProvider,
  isAgency,
  enabled = true
}) => {
  const canFetch = isAgency
    ? !!(packageCode && product)
    : !!(packageCode && product && partner)

  return useQuery({
    queryKey: [BENEFITS_LIST_KEY, packageCode, product, partner, isAgency ? 'agency' : 'b2c'],
    queryFn: async () => {
      if (isAgency) {
        const query = {
          package_code: packageCode,
          product_key: product,
          insurance_provider: insuranceProvider,
          package: packageCode,
          product
        }
        const res = await agencyApi.getAgencyBenefits({ payload: { query } })
        const data = assertApiOk(res)
        return {
          benefitList: data,
          isMultiBenefitClaimable: false,
          message: 'success'
        }
      }

      const res = await claimApi.getBenefitsV4({
        query: { package: packageCode, product, partner }
      })
      const data = assertApiOk(res)
      return {
        benefitList: data.benefit_list_data || [],
        isMultiBenefitClaimable: data.is_multi_benefit_claimable,
        message: 'success'
      }
    },
    enabled: enabled && canFetch
  })
}

export const useQuestionnaireQuery = ({ addonIds, enabled = true }) =>
  useQuery({
    queryKey: [QUESTIONNAIRE_KEY, addonIds],
    queryFn: async () => {
      const res = await claimApi.getQuetionnaireList({ addons: addonIds })
      if (![200, 201].includes(res?.status)) {
        throw new Error(res?.data?.message || 'Error')
      }
      return res.data?.data || []
    },
    enabled: enabled && addonIds?.length > 0
  })
