import { GENERAL_API_ERROR_MESSAGE } from '../../helpers/showApiError'

const pickResponseError = (data) => {
  if (!data || typeof data !== 'object') {
    return ''
  }
  if (typeof data.error === 'string' && data.error.trim()) {
    return data.error
  }
  if (typeof data.message === 'string' && data.message.trim()) {
    return data.message
  }
  return ''
}

export const getApiErrorMessage = (res) => {
  const specific = pickResponseError(res?.data)
  if (specific) {
    return specific
  }
  return GENERAL_API_ERROR_MESSAGE
}

export const assertApiOk = (res, successStatuses = [200]) => {
  if (!res || !successStatuses.includes(res.status)) {
    throwApiErrorFromResponse(res)
  }
  return res.data
}

export const throwApiErrorFromResponse = (res) => {
  const err = new Error(getApiErrorMessage(res))
  err.code = res?.data?.code
  err.status = res?.status
  throw err
}
