import { useQuery } from '@tanstack/react-query'
import request from '../../axios/claim'

export const ASDP_TRAVEL_USER_LIST_KEY = 'asdp-travel-user-list'

export const useAsdpTravelUserList = ({ benefit_id, application_no, internal_id }, options) =>
  useQuery({
    queryKey: [ASDP_TRAVEL_USER_LIST_KEY, benefit_id, application_no],
    queryFn: () =>
      request.getAsdpEligibleUserList({ benefit_id, application_no, internal_id })
        .then((res) => res.data.data),
    enabled: !!(benefit_id && application_no),
    ...options
  })
