import { useEffect, useMemo, useState } from 'react'
import { useAsdpTravelUserList } from '../../request/query/claim/asdpTravelUserList'
import { LANG_STRINGS } from '../../constants/lang'
import AsdpTravelUserCard from '../AsdpTravelUserCard'
import {
  AsdpTravelUserListContainer,
  CardListWrapper,
  SearchInput
} from './asdpTravelUserList.style'
import Loader from '../Loader'
import IntlMessages from '../utility/intlMessages'
import {
  ErrorWrapper,
  ErrorImage,
  BenefitErrorText
} from '../../containers/BenefitList/benefitList.style'
import { AlertRedIcon } from '../../image'
import { Center } from '../../containers/PolicyList/policyList.style'

function AsdpTravelUserCardList ({
  benefitId,
  applicationNo,
  internalId,
  onChange = () => { },
  onRemainingTSIChange = () => { },
  onHasTripCancellationBenefitChange = () => { }
}) {
  const { data, isLoading, isError } = useAsdpTravelUserList({
    benefit_id: benefitId,
    application_no: applicationNo,
    internal_id: internalId
  })

  const [selectedUserList, setSelectedUserList] = useState([])
  const [searchText, setSearchText] = useState('')

  const selectedParticipantNumbers = useMemo(
    () => new Set(selectedUserList.map((u) => u.participant_number)),
    [selectedUserList]
  )

  const onChangeHandler = (e, { name, ticketId, participant_number }) => {
    const checked = e.target.checked
    let newUserList = [...selectedUserList]
    if (checked) {
      newUserList.push({ name, participant_number })
    } else {
      newUserList = newUserList.filter(({ participant_number: no }) => participant_number !== no)
    }
    setSelectedUserList(newUserList)
  }

  useEffect(() => {
    onChange(selectedUserList)
  }, [
    onChange,
    selectedUserList
  ])

  useEffect(() => {
    if (data?.benefit_remaining_TSI != null) {
      onRemainingTSIChange(data.benefit_remaining_TSI)
    }
    if (data?.has_trip_cancellation_benefit != null) {
      onHasTripCancellationBenefitChange(data.has_trip_cancellation_benefit)
    }
  }, [
    data,
    onRemainingTSIChange,
    onHasTripCancellationBenefitChange
  ])

  if (isLoading) {
    return (
      <Center>
        <Loader />
      </Center>
    )
  }

  if (isError) {
    return (
      <ErrorWrapper>
        <ErrorImage src={AlertRedIcon} />
        <BenefitErrorText>
          <IntlMessages id={LANG_STRINGS.failedToLoadEligibleUsers} />
        </BenefitErrorText>
      </ErrorWrapper>
    )
  }

  const users = data?.users || []

  const query = searchText.toLowerCase().trim()
  const visibleUsers = query
    ? users.filter((u) => {
        if (selectedParticipantNumbers.has(u.participant_number)) return true
        const name = (u.name || '').toLowerCase()
        const ticket = (u.ticket_id || '').toLowerCase()
        return name.includes(query) || ticket.includes(query)
      })
    : users

  return (
    <AsdpTravelUserListContainer>
      <SearchInput
        type='text'
        placeholder='Search...'
        value={searchText}
        onChange={(e) => setSearchText(e.target.value)}
      />
      <CardListWrapper>
        {
          visibleUsers.map((user) => {
            const {
              name,
              ticket_id: ticketId,
              participant_number,
              is_eligible: enabled
            } = user
            const userDetails = [
              {
                key: LANG_STRINGS.ticketId,
                value: ticketId
              }
            ]
            const disabledText = enabled ? '' : LANG_STRINGS.individualAmountTapTravelExceededCopyRight
            return (
              <AsdpTravelUserCard
                key={ticketId}
                userTitle={name}
                enabled={enabled}
                onChange={(e) => onChangeHandler(e, { name, ticketId, participant_number })}
                disabledText={disabledText}
                userDetails={userDetails}
              />
            )
            })
          }
        </CardListWrapper>
    </AsdpTravelUserListContainer>
  )
}

export default AsdpTravelUserCardList
