import { FormattedMessage } from 'react-intl'
import { COLORS } from '../../constants/colors'
import CustomCheckbox from '../CustomCheckBox'
import IntlMessages from '../utility/intlMessages'

import {
  Detail,
  DisabledUserText,
  Info,
  Title,
  Wrapper
} from './asdpTravelCard.style'

function AsdpTravelUserCard ({
  userTitle = 'title',
  userDetails = [],
  enabled = true,
  disabledText = '',
  onChange = () => { }
}) {
  const disabled = !enabled
  return (
    <div>
      <Wrapper disabled={disabled}>
        <Info>
          <Title>{userTitle}</Title>
          {
            userDetails.map(({ key, value }) => {
              return (
                <Detail>
                  <IntlMessages id={key} />
                  &nbsp;
                  <IntlMessages id={value} />
                </Detail>
              )
            })
          }
        </Info>
        {
          disabled
            ? null
            : <CustomCheckbox
              width='20px'
              height='20px'
              checkedPosition={{
                height: 13,
                width: 7,
                left: 5,
                bottom: 3,
                borderRadius: 2
              }}
              checkedBoxLeftAllignment='40px'
              checkedBoxTopAlignment='6px'
              unCheckedBorderColor={COLORS.monoChromeGrey}
              borderColor={COLORS.white}
              checkedColor={COLORS.tapPartnerBlue}
              onChange={onChange}
            />
        }
      </Wrapper>
      {
        disabledText
          ? <DisabledUserText>
            <FormattedMessage id={disabledText} />
          </DisabledUserText>
          : null
      }
    </div>
  )
}

export default AsdpTravelUserCard
