import React from 'react'
import { connect } from 'react-redux'
import PropTypes from 'prop-types'
import { injectIntl } from 'react-intl'
import { QuestionsStyle } from './addOns-Content.style'
import IntlMessages from '../../components/utility/intlMessages'
import { Button, Col, Row, Spin } from 'antd'
import QuestionsData from './add-questions-content'
import claimActions from '../../redux/claim/actions'
import ErrorAlert from '../../components/ErrorAlert'

const { getQuetionnaireList, resetReduxState } = claimActions

class AddOnsContent extends React.Component {
  state = {
    questionsData: [],
    totalQuestionsList: [],
    showSubmitBtn: true
  };

  componentDidMount () {
    const { totalQuestionsListError = false, totalQuestionsList = [] } = this.props
    if (totalQuestionsListError) this.setState({ showSubmitBtn: false })
    const updatedQuestionsList = totalQuestionsList.map((item) => {
      return { id: item.id, response: false, display_text: item.display_text }
    }, [])
    const updatedQuestionsResponse = totalQuestionsList.map((item) => {
      return { id: item.id, response: false }
    })
    this.setState({ questionsData: updatedQuestionsList })
    this.props.handleQuestionsChange(updatedQuestionsResponse)
  }
  handleAddOnsDataChange = (id, flag) => {
    const updatedAddOnsData = this.state.questionsData.map((data) => {
      return data.id === id ? { ...data, response: flag } : data
    })
    const updatedQuestionsResponse = this.state.questionsData.map((data) => {
      return data.id === id
        ? { id, response: flag }
        : { id: data.id, response: data.response }
    })
    this.setState({ questionsData: updatedAddOnsData })
    this.props.handleQuestionsChange(updatedQuestionsResponse)
  };

  render () {
    const {
      handleCloseAddOns = () => {},
      handleSubmit = () => {},
      totalQuestionsList,
      totalQuestionsListError = false,
      totalQuestionsListMessage = '',
      questionsListLoading
    } = this.props
    return (
      <>
        {!!totalQuestionsListError && !!totalQuestionsListMessage && (
          <ErrorAlert message={this.props.intl.formatMessage({ id: 'Ada kesalahan di sistem kami, silahkan hubungi CS' })} type='error' />
        )}
        <Spin spinning={!!questionsListLoading} tip='Loading...'>
          <QuestionsStyle className>
            <div className='addons-questions-list-ctn'>
              {totalQuestionsList.map((questions) => {
                return (
                  <QuestionsData
                    data={questions}
                    handleAddOnsDataChange={this.handleAddOnsDataChange}
                  />
                )
              })}
            </div>
            <div className='addons-submit-btn-ctn'>
              <Row
                type='flex'
                justify='space-between'
                align='middle'
                className='action-btns'
              >
                <Col xs={11}>
                  <Button
                    type='default'
                    size='large'
                    onClick={() => handleCloseAddOns()}
                  >
                    <div>
                      <IntlMessages id='BATAL' />
                    </div>
                  </Button>
                </Col>
                <Col xs={11}>
                  <Button
                    type='primary'
                    size='large'
                    className='create-claim-button'
                    disabled={!this.state.showSubmitBtn}
                    onClick={() => {
                      handleSubmit()
                    }}
                  >
                    <IntlMessages id='LANJUT' />
                  </Button>
                </Col>
              </Row>
            </div>
          </QuestionsStyle>
        </Spin>
      </>
    )
  }
}

AddOnsContent.propTypes = {
  questionsData: PropTypes.array
}

AddOnsContent.defaultProps = {
  questionsData: []
}

export default connect(
  (state, ownProps) => ({
    totalQuestionsList: ownProps.totalQuestionsList || state.Claim.totalQuestionsList,
    totalQuestionsListError: ownProps.totalQuestionsListError ?? state.Error.GET_QUESTIONS_LIST,
    totalQuestionsListMessage: ownProps.totalQuestionsListMessage || state.Claim.totalQuestionsListMessage,
    questionsListLoading: ownProps.questionsListLoading ?? state.Loading.GET_QUESTIONS_LIST
  }),
  {
    getQuetionnaireList,
    resetReduxState
  }
)(injectIntl(AddOnsContent))
