import { useState } from 'react'
import { ArrowDown } from '../../image'
import {
  BenefitDescriptionText,
  BenefitGroupContainer,
  BenefitGroupText,
  BenefitListContainer,
  BenefitText,
  BenefitWrapper,
  SingleBenefitListContainer
} from './benefitList.style'
import CustomCheckBox from '../../components/CustomCheckBox'
import { COLORS } from '../../constants/colors'
import IntlMessages from '../../components/utility/intlMessages'

function MultiBenefitList ({ benefitList = [], onChange, selectedBenefit = [] }) {
  const [closedBenefits, setClosedBenefits] = useState([])

  const openBenefitGroup = (benefitGroupId) => {
    const newBenefitGroupId = [...closedBenefits].filter((item) => item !== benefitGroupId)
    setClosedBenefits(newBenefitGroupId)
  }

  const closeBenefitGroup = (benefitGroupId) => {
    setClosedBenefits([...closedBenefits, benefitGroupId])
  }

  return (
    <SingleBenefitListContainer>
      {
        benefitList.map((ben) => {
          const {
            benefit_group_id: benefitGroupId = '',
            benefits = [],
            benefit_group_description: benefitGroupDescription
          } = ben
          return (
            <BenefitGroupContainer key={benefitGroupDescription}>
              <BenefitGroupText>
                <IntlMessages id={benefitGroupDescription} />
                {
                  benefits.length > 1
                    ? (
                      closedBenefits.includes(benefitGroupId)
                        ? (
                          <img onClick={() => openBenefitGroup(benefitGroupId)} src={ArrowDown} width={16} height={16} className='transform-360' />
                        )
                        : <img onClick={() => closeBenefitGroup(benefitGroupId)} src={ArrowDown} width={16} height={16} className='transform-180' />
                    )
                    : null
                }
                {
                  !benefits.length
                    ? (
                      <CustomCheckBox
                        onChange={(e) => onChange(e, ben)}
                        width='20px'
                        height='20px'
                        checkedPosition={{
                          height: 13,
                          width: 7,
                          left: 5,
                          bottom: 3,
                          borderRadius: 2
                        }}
                        unCheckedBorderColor={COLORS.monoChromeGrey}
                        borderColor={COLORS.white}
                        checkedColor={COLORS.tapPartnerBlue}
                      />
                    )
                    : null
                }
              </BenefitGroupText>
              {
                !closedBenefits.includes(benefitGroupId) && benefits.length
                  ? (
                    benefits.map((benefit) => {
                      const { benefit_name: benefitName = '', description, is_active_config: isActiveConfig = true } = benefit
                      return (
                        <BenefitListContainer key={benefitName}>
                          <BenefitWrapper>
                            <BenefitText>
                              <IntlMessages id={benefitName} />
                            </BenefitText>
                            <BenefitDescriptionText>
                              <IntlMessages id={description} />
                            </BenefitDescriptionText>
                          </BenefitWrapper>

                          { isActiveConfig
                            ? (
                              <div>
                                <CustomCheckBox
                                  onChange={(e) => onChange(e, benefit)}
                                  width='20px'
                                  height='20px'
                                  checkedPosition={{
                                    height: 14,
                                    width: 8,
                                    left: 4,
                                    bottom: 3,
                                    borderRadius: 2
                                  }}
                                  unCheckedBorderColor={COLORS.monoChromeGrey}
                                  borderColor={COLORS.white}
                                  checkedColor={COLORS.tapPartnerBlue}
                                />
                              </div>
                            )
                            : null
                          }
                        </BenefitListContainer>
                      )
                    })
                  )
                  : null
              }
            </BenefitGroupContainer>
          )
        })
      }
    </SingleBenefitListContainer>

  )
}

export default MultiBenefitList
