import {
  Modal,
  Icon,
  ModalContainer,
  ModalButton,
  ModalHeader,
  ModalBody,
  HeaderText,
  Shadow
} from './Modal.styles'

import CloseIcon from '../../image/close.png'
import { useEffect } from 'react'
import { getAssets } from '../../helpers/utility'

const CustomModal = ({
  headerBackgroundColor = '',
  footer = null,
  width = '',
  modalIsOpen = true,
  modalBodyHeight = '',
  closeModal,
  headerText = '',
  leftButton = true,
  leftButtonText = 'OKE',
  rightButton = false,
  markupText = '',
  onRightButtonClick,
  onLeftButtonClick,
  leftButtonStyle = {},
  rightButtonStyle = {},
  rightButtonText = '',
  isCloseIcon = true,
  onCloseIconClick = () => {},
  closeOnShadowDisabled = false,
  modalBodyStyle = {},
  height = '',
  headerTextColor = ''
}) => {
  useEffect(() => {
    if (modalIsOpen) {
      const bodyStyle = document.querySelector('body').style
      bodyStyle.overflow = 'hidden'
    } else {
      const bodyStyle = document.querySelector('body').style
      bodyStyle.overflow = 'auto'
    }
    return () => {
      const bodyStyle = document.querySelector('body').style
      bodyStyle.overflow = 'auto'
    }
  }, [modalIsOpen])
  return (
    <>
      <Shadow isOpen={modalIsOpen} onClick={closeOnShadowDisabled ? () => {} : closeModal} />
      <Modal
        height={height}
        width={width}
        isOpen={modalIsOpen}
      >
        <ModalHeader background={headerBackgroundColor}>
          <HeaderText color={headerTextColor}>
            {headerText}
          </HeaderText>
          {
            isCloseIcon
              ? <Icon src={getAssets().closeIcon || CloseIcon} alt='close' onClick={closeModal} />
              : null
          }
        </ModalHeader>
        <ModalBody style={{ ...modalBodyStyle }} modalBodyHeight={modalBodyHeight}>
          {markupText}
        </ModalBody>
        { footer || <ModalContainer>
          {leftButton && (
            <ModalButton
              fullWidth={!(leftButton && rightButton)}
              onClick={onLeftButtonClick}
              customStyle={leftButtonStyle}
            >
              {leftButtonText}
            </ModalButton>
          )}

          {rightButton && (
            <ModalButton
              onClick={onRightButtonClick}
              customStyle={rightButtonStyle}
            >
              {' '}
              {rightButtonText}
            </ModalButton>
          )}
        </ModalContainer>
        }
      </Modal>
    </>
  )
}

export default CustomModal
