import { useState } from 'react'
import IntlMessages from '../../components/utility/intlMessages'
import {
  QuestionsDataContainer,
  AddOnsListYesNoContainer,
  AddOnsListYes,
  AddOnsListNo,
  LogoContainer
} from './addOns-Content.style'
import Check from '../../image/check_line.png'
import Cross from '../../image/cross_line.png'
import WhiteCheck from '../../image/white-check-line.png'
import WhiteCross from '../../image/white-cross-line.png'

const QuestionsData = (props) => {
  const [btnColor, setBtnColor] = useState('grey')
  const { data: { id = '', display_text: displayText = '' } = {}, handleAddOnsDataChange } =
    props

  const handleChange = (id, flag) => {
    handleAddOnsDataChange(id, flag)
    setBtnColor(flag ? 'green' : 'red')
  }
  return (
    <QuestionsDataContainer key={id} className='addons-questions-container'>
      <IntlMessages className='capitalized-text' id={displayText} />
      <AddOnsListYesNoContainer>
        <AddOnsListYes
          onClick={() => handleChange(id, true)}
          btnColor={btnColor}
        >
          <div>
            <IntlMessages id='YA' />
          </div>
          <LogoContainer>
            <img src={btnColor === 'green' ? WhiteCheck : Check} alt='check-mark' />
          </LogoContainer>
        </AddOnsListYes>
        <AddOnsListNo
          onClick={() => handleChange(id, false)}
          btnColor={btnColor}
        >
          <div>
            <IntlMessages id='TIDAK' />
          </div>
          <LogoContainer>
            <img src={btnColor === 'red' ? WhiteCross : Cross} alt='check-mark' />
          </LogoContainer>
        </AddOnsListNo>
      </AddOnsListYesNoContainer>
    </QuestionsDataContainer>
  )
}
export default QuestionsData
