/* eslint-disable react/jsx-filename-extension */
import React, { useEffect, useState } from 'react'
import Radio from '../../components/Radio'
import { ArrowDown } from '../../image'
import {
  BenefitDescriptionText,
  BenefitDocumentItem,
  BenefitDocumentListContainer,
  BenefitGroupContainer,
  BenefitGroupText,
  BenefitText,
  BenefitWrapper,
  SingleBenefitListContainer,
} from './benefitList.style'
import IntlMessages from '../../components/utility/intlMessages'
import { LANG_STRINGS } from '../../constants/lang'

function SingleBenefitList({ benefitList = [], onChange }) {
  const [closedBenefits, setClosedBenefits] = useState([])
  const [selectedKey, setSelectedKey] = useState(null)
  const [selectedBenefitId, setSelectedBenefitId] = useState(null)

  // On mount / when list changes: close all groups
  useEffect(() => {
    if (!Array.isArray(benefitList) || benefitList.length === 0) {
      setClosedBenefits([])
      return
    }

    const groupIds = benefitList
      .map((g) => g.benefit_group_id || '')
      .map((id, i) => (id === '' ? `__idx_${i}` : id))
    const groupsWithBenefits = benefitList.map((g, i) => ({
      id: groupIds[i],
      has: Array.isArray(g.benefits) && g.benefits.length > 0,
    }))

    // close all groups that have benefits
    const closed = groupsWithBenefits.filter((g) => g.has).map((g) => g.id)
    setClosedBenefits(closed)
  }, [benefitList])

  const toggleBenefitGroup = (groupId) => {
    setClosedBenefits((prev) =>
      prev.includes(groupId)
        ? prev.filter((id) => id !== groupId)
        : [...prev, groupId]
    )
  }

  const selectBenefit = (e, benefit, key) => {
    const id = benefit && (benefit.benefit_id || benefit.benefitId || null)
    setSelectedKey(key)
    setSelectedBenefitId(id)
    if (typeof onChange === 'function') onChange(e, benefit)
  }

  return (
    <SingleBenefitListContainer>
      {benefitList.map((group, groupIndex) => {
        const benefitGroupIdRaw = group.benefit_group_id
        const benefitGroupId = benefitGroupIdRaw || `__idx_${groupIndex}`
        const benefits = Array.isArray(group.benefits) ? group.benefits : []
        const benefitGroupName = group.benefit_group_name

        return (
          <div key={benefitGroupId} style={{ borderBottom: '2px solid #DDD' }}>
            <BenefitGroupText
              onClick={() =>
                benefits.length > 0 && toggleBenefitGroup(benefitGroupId)
              }
              style={{
                cursor: benefits.length > 0 ? 'pointer' : 'default',
                marginBottom: '16px',
              }}
            >
              <IntlMessages id={benefitGroupName} />
              {benefits.length > 0 && (
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation()
                    toggleBenefitGroup(benefitGroupId)
                  }}
                  aria-expanded={!closedBenefits.includes(benefitGroupId)}
                  style={{
                    border: 0,
                    background: 'transparent',
                    padding: 0,
                    marginLeft: 8,
                  }}
                >
                  <img
                    src={ArrowDown}
                    width={16}
                    height={16}
                    className={
                      closedBenefits.includes(benefitGroupId)
                        ? 'transform-360'
                        : 'transform-180'
                    }
                    alt=""
                  />
                </button>
              )}
            </BenefitGroupText>

            {/* Groups without individual benefits: render as a selectable item */}
            {benefits.length === 0 && (
              <BenefitGroupContainer
                style={{
                  cursor: 'pointer',
                  border:
                    selectedKey === `group:${benefitGroupId}`
                      ? '2px solid #1890ff'
                      : '1px solid #d9d9d9',
                  marginBottom: '16px',
                }}
                onClick={(e) => selectBenefit(e, group, `group:${benefitGroupId}`)}
              >
                <BenefitWrapper>
                  <BenefitText>
                    <IntlMessages id={benefitGroupName} />
                  </BenefitText>
                  <Radio
                    checked={selectedKey === `group:${benefitGroupId}`}

                  />
                </BenefitWrapper>
              </BenefitGroupContainer>
            )}

            {/* Individual benefit cards */}
            {!closedBenefits.includes(benefitGroupId) &&
              benefits.length > 0 &&
              benefits.map((benefit, bIndex) => {
                const benefitId =
                  benefit.benefit_id || benefit.benefitId || null
                const benefitKey = `benefit:${benefitGroupId}:${
                  benefitId != null ? benefitId : bIndex
                }`
                const isSelected =
                  benefitId != null
                    ? selectedBenefitId === benefitId
                    : selectedKey === benefitKey
                const isActive = benefit.is_active_config !== false

                return (
                  <BenefitGroupContainer
                    key={
                      benefit.benefit_id ||
                      benefit.benefit_name ||
                      `${benefitGroupId}-${bIndex}`
                    }
                    style={{
                      cursor: isActive ? 'pointer' : 'default',
                      border: isSelected
                        ? '2px solid #1890ff'
                        : '1px solid #d9d9d9',
                      marginBottom: '16px',
                    }}
                    onClick={(e) => selectBenefit(e, benefit, benefitKey)}
                  >
                    <BenefitWrapper>
                      <div
                        style={{
                          display: 'flex',
                          justifyContent: 'space-between',
                          alignItems: 'flex-start',
                        }}
                      >
                        <div style={{ flex: 1 }}>
                          <BenefitText>
                            <IntlMessages id={benefit.benefit_name} />
                          </BenefitText>

                          {isSelected && (
                            <>
                              {benefit.description && (
                                <BenefitDescriptionText>
                                  <IntlMessages id={benefit.description} />
                                </BenefitDescriptionText>
                              )}

                              {Array.isArray(benefit.documents_required) &&
                                benefit.documents_required.length > 0 && (
                                  <>
                                    <BenefitDescriptionText>
                                      <IntlMessages
                                        id={LANG_STRINGS.benefitDocumentText}
                                      />
                                      :
                                    </BenefitDescriptionText>
                                    <BenefitDocumentListContainer>
                                      {benefit.documents_required.map(
                                        (item, i) => (
                                          <BenefitDocumentItem
                                            key={
                                              item.user_label || item.id || i
                                            }
                                          >
                                            {item.user_label}
                                          </BenefitDocumentItem>
                                        )
                                      )}
                                    </BenefitDocumentListContainer>
                                  </>
                                )}
                            </>
                          )}
                        </div>

                        {isActive && (
                          <div style={{ marginLeft: '16px' }}>
                            <Radio
                              checked={isSelected}
                            />
                          </div>
                        )}
                      </div>
                    </BenefitWrapper>
                  </BenefitGroupContainer>
                )
              })}
          </div>
        )
      })}
    </SingleBenefitListContainer>
  )
}

export default SingleBenefitList
