import { useCallback, useEffect, useRef, useState } from 'react'
import { FormattedMessage } from 'react-intl'
import { useHistory } from 'react-router'

import Modal from '../../components/Modal'
import SingleBenefitList from './singleBenefitListUI'
import { LANG_STRINGS } from '../../constants/lang'
import { COLORS } from '../../constants/colors'
import IntlMessages from '../../components/utility/intlMessages'
import { useBenefitsListQuery, useQuestionnaireQuery } from '../../request/query/claim/benefits'
import {
  useCreateClaimMutation,
  useFamilyCreateClaimMutation,
  useValidateClaimMutation
} from '../../request/query/claim/claimMutations'
import { useFamilyEligibleUserList } from '../../request/query/claim/familyUsers'

import {
  FooterButtonWrapper,
  CenterBodyWrapper,
  FooterButton,
  FooterWrapper,
  ModalBodyWrapper,
  NoBenefitCopyRightText,
  ErrorWrapper,
  ErrorImage,
  BenefitErrorText,
  ErrorBenefitTextName,
  ErrorText,
  ErrorBenefitCustomerContact,
  ErrorCloseButton,
  MobileFooterButtonWrapper,
  MobileFooterButton,
  SecondClaimOnSameBenefit
} from './benefitList.style'
import { benefitSteps } from '../../constants'
import AddOnsContent from '../policyApp/addOns-content'
import Loader from '../../components/Loader'
import { AlertRedIcon, InfoIcon } from '../../image'
import { getAssets, formatCurrency, isAsdpTripCancellationBenefit } from '../../helpers/utility'
import MultiBenefitList from './multiBenefitUI'
import TapTravelUserCardList from '../../components/TapTravelUserList'
import AsdpTravelUserCardList from '../../components/AsdpTravelUserList'
import { Center } from '../PolicyList/policyList.style'
import { useIsMobile } from '../../hooks/useIsMobile'

function BenefitList ({
  isAgency,
  closeBenefitModalPolicyList,
  benefitQueryParams,
}) {
  const {
    product,
    partner,
    internalId,
    applicationNo,
    packageCode,
    isFamilyPolicy,
    isAsdpFerryTravelPolicy,
    insuranceprovider,
    additionalProtection = []
  } = benefitQueryParams

  const history = useHistory()
  const isMobile = useIsMobile()

  const {
    data: benefitsData,
    isError: benefitsListError,
    error: benefitsListFetchError,
    isLoading: benefitsListLoading,
    isSuccess: benefitsListSuccess
  } = useBenefitsListQuery({
    packageCode,
    product,
    partner,
    insuranceProvider: insuranceprovider,
    isAgency
  })

  const addonIds = Array.isArray(additionalProtection) && additionalProtection.length
    ? additionalProtection.map(({ id }) => id)
    : []

  const {
    data: questionnaireData = [],
    isLoading: questionsListLoading,
    isError: totalQuestionsListError
  } = useQuestionnaireQuery({
    addonIds,
    enabled: addonIds.length > 0
  })

  const validateClaimMutation = useValidateClaimMutation()
  const createClaimMutation = useCreateClaimMutation()
  const familyCreateClaimMutation = useFamilyCreateClaimMutation()

  const benefitList = benefitsData?.benefitList || []
  const isMultiBenefitClaimable = benefitsData?.isMultiBenefitClaimable || false
  const getBenefitListUserMessage = benefitsListFetchError?.message
    || benefitsData?.message
    || 'Maaf, kami tidak dapat menampilkan benefit anda'

  const [selectedBenefit, setSelectedBenefit] = useState(null)
  const [validateClaimErrorMessage, setValidateClaimError] = useState('')
  const [currStep, setCurrStep] = useState(benefitSteps.loading)
  const [addOnUserResponse, setAddOnUserResponse] = useState([])
  const [selectedTapTravelUserList, setTapTravelSelectedUserList] = useState([])
  const [selectedAsdpTravelUserList, setAsdpTravelSelectedUserList] = useState([])
  const [asdpBenefitRemainingTSI, setAsdpBenefitRemainingTSI] = useState(0)
  const [hasTripCancellationBenefit, setHasTripCancellationBenefit] = useState(false)
  const pendingPostValidateRef = useRef(null)

  const selectedBenefitId = selectedBenefit?.benefit_id

  const {
    data: familyUserData,
    isLoading: tapTravelUserListLoading,
    isError: getTapTravelUserListError
  } = useFamilyEligibleUserList({
    benefit_id: selectedBenefitId,
    application_no: applicationNo,
    internal_id: internalId
  }, {
    enabled: !!(isFamilyPolicy && selectedBenefitId)
  })

  const tapTravelUserList = familyUserData?.userList || []
  const familyEligibleUserBenefitRemainingTSI = familyUserData?.benefitRemainingTSI || 0
  const getFamilyBenefitUserMessage = 'Ada kesalahan di sistem kami, silahkan hubungi CS'

  const cleanAllState = useCallback(() => {
    setValidateClaimError('')
    setAddOnUserResponse([])
    setSelectedBenefit(null)
    setHasTripCancellationBenefit(false)
    pendingPostValidateRef.current = null
    setCurrStep(benefitSteps.loading)
    validateClaimMutation.reset()
    createClaimMutation.reset()
    familyCreateClaimMutation.reset()
  }, [validateClaimMutation, createClaimMutation, familyCreateClaimMutation])

  useEffect(() => {
    return () => {
      validateClaimMutation.reset()
      createClaimMutation.reset()
      familyCreateClaimMutation.reset()
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  useEffect(() => {
    if (benefitsListLoading) return

    if (benefitsListError) {
      setCurrStep(benefitSteps.errorBenefitMessage)
      return
    }

    if (!benefitsListSuccess) return

    if (!benefitList.length) {
      setCurrStep(benefitSteps.errorBenefitMessage)
      return
    }

    if (isMultiBenefitClaimable) {
      setSelectedBenefit([])
      setCurrStep(benefitSteps.multiBenefitList)
      return
    }

    setCurrStep(benefitSteps.singleBenefitList)
  }, [
    benefitsListLoading,
    benefitsListError,
    benefitsListSuccess,
    benefitList,
    isMultiBenefitClaimable
  ])

  const closeBenefitModal = useCallback(() => {
    closeBenefitModalPolicyList()
    cleanAllState()
  }, [closeBenefitModalPolicyList, cleanAllState])

  const benefitListChangeHandler = useCallback((e, benefit) => {
    e.stopPropagation()
    setSelectedBenefit(benefit)
  }, [])

  const multiBenefitListChangeHandler = useCallback((e, benefit) => {
    e.stopPropagation()
    const checked = e.target.checked
    setSelectedBenefit((prev) => {
      let newBenefitList = [...(prev || [])]
      if (checked) {
        newBenefitList = [...newBenefitList, benefit]
      } else {
        newBenefitList = newBenefitList.filter(({ benefit_id: id }) => id !== benefit.benefit_id)
      }
      return newBenefitList
    })
  }, [])

  const runCreateClaim = useCallback((payload, options = {}) => {
    const useAgency = options.isAgency ?? isAgency
    const isFamilyPayload = !!payload.insured_list && !useAgency
    const mutation = isFamilyPayload ? familyCreateClaimMutation : createClaimMutation

    mutation.mutate(
      isFamilyPayload ? payload : { isAgency: useAgency, ...payload },
      {
        onSuccess: (claimId) => {
          history.push(`/claimdetail/${claimId}`)
        },
        onError: (err) => {
          setCurrStep(benefitSteps.validateOrCreateClaimMessage)
          setValidateClaimError(err.message)
        }
      }
    )
  }, [createClaimMutation, familyCreateClaimMutation, history, isAgency])

  const createClaim = useCallback(() => {
    if (!selectedBenefit) return
    setCurrStep(benefitSteps.loading)

    if (!isMultiBenefitClaimable) {
      const { benefit_id: id } = selectedBenefit
      runCreateClaim({
        benefitId: id,
        benefit_id: id,
        applicationNo,
        questionData: addOnUserResponse,
        source: 'direct',
        internal_id: internalId,
        application_no: applicationNo
      })
      return
    }

    if (!selectedBenefit.length) return
    const id = selectedBenefit.map(({ benefit_id: benefitId }) => benefitId)
    runCreateClaim({
      benefitId: id,
      benefit_id: id,
      applicationNo,
      questionData: addOnUserResponse,
      source: 'direct',
      internal_id: internalId,
      application_no: applicationNo
    })
  }, [
    selectedBenefit,
    isMultiBenefitClaimable,
    runCreateClaim,
    applicationNo,
    addOnUserResponse,
    internalId
  ])

  const asdpTripCancellationCreateClaim = useCallback(() => {
    setCurrStep(benefitSteps.loading)
    const payload = {
      benefit_id: selectedBenefit.benefit_id,
      benefitId: selectedBenefit.benefit_id,
      application_no: applicationNo,
      questionData: addOnUserResponse,
      source: 'direct',
      insured_list: [],
      internal_id: internalId,
      has_trip_cancellation_benefit: true
    }
    if (isAgency) {
      runCreateClaim(payload, { isAgency: true })
    } else {
      runCreateClaim(payload)
    }
  }, [
    selectedBenefit,
    applicationNo,
    addOnUserResponse,
    internalId,
    isAgency,
    runCreateClaim
  ])

  const handleValidateSuccess = useCallback((validateClaimData) => {
    const {
      claim_id: claimId = null,
      is_claimable: isClaimable = false,
      is_first_claim: isFirstClaim = false,
      error_message: errorMessage
    } = validateClaimData

    if (isClaimable && !isFirstClaim) {
      setCurrStep(benefitSteps.secondClaimOnSameBenefit)
      setValidateClaimError(errorMessage)
      return
    }

    if (claimId) {
      history.push(`/claimdetail/${claimId}`)
      return
    }
    if (!isClaimable) {
      setCurrStep(benefitSteps.validateOrCreateClaimMessage)
      return
    }
    if (isFirstClaim) {
      if (pendingPostValidateRef.current === 'asdpTripCancellation') {
        pendingPostValidateRef.current = null
        asdpTripCancellationCreateClaim()
        return
      }
      createClaim()
    }
  }, [asdpTripCancellationCreateClaim, createClaim, history])

  const validateClaim = useCallback(() => {
    if (!selectedBenefit) return

    let payload
    if (!isMultiBenefitClaimable) {
      const { benefit_id: id } = selectedBenefit
      payload = {
        benefit_id: id,
        application_no: applicationNo,
        internal_id: internalId,
        product_key: product,
        package_code: packageCode
      }
    } else {
      if (!selectedBenefit.length) return
      const id = selectedBenefit.map(({ benefit_id: benefitId }) => benefitId).join(',')
      payload = {
        benefit_id: id,
        application_no: applicationNo,
        internal_id: internalId,
        product_key: product,
        package_code: packageCode
      }
    }

    validateClaimMutation.mutate(
      { isAgency, ...payload },
      {
        onSuccess: handleValidateSuccess,
        onError: (err) => {
          setCurrStep(benefitSteps.validateOrCreateClaimMessage)
          setValidateClaimError(err.message)
        }
      }
    )
  }, [
    selectedBenefit,
    isMultiBenefitClaimable,
    applicationNo,
    internalId,
    product,
    packageCode,
    isAgency,
    validateClaimMutation,
    handleValidateSuccess
  ])

  const onContinueClickHandler = useCallback((e) => {
    e.stopPropagation()
    if (isFamilyPolicy) {
      setCurrStep(benefitSteps.tapTravelUserList)
      return
    }
    if (isAsdpFerryTravelPolicy) {
      if (isAsdpTripCancellationBenefit(selectedBenefit)) {
        // Validate first (isClaimable / isFirstClaim guardrails). Create still skips user list.
        pendingPostValidateRef.current = 'asdpTripCancellation'
        setCurrStep(benefitSteps.loading)
        validateClaim()
        return
      }
      setCurrStep(benefitSteps.asdpTravelUserList)
      return
    }
    setCurrStep(benefitSteps.loading)
    validateClaim()
  }, [isFamilyPolicy, isAsdpFerryTravelPolicy, selectedBenefit, validateClaim])

  const onNextClickHandler = useCallback((e) => {
    e.stopPropagation()
    setCurrStep(benefitSteps.addOnQuestionList)
  }, [])

  const handleQuestionsChange = useCallback((response) => {
    setAddOnUserResponse(response)
  }, [])

  const handleSubmit = useCallback(() => {
    setCurrStep(benefitSteps.loading)
    validateClaim()
  }, [validateClaim])

  const handleCloseAddOns = useCallback(() => {
    closeBenefitModal()
  }, [closeBenefitModal])

  const tapTravelCreateClaim = useCallback((e) => {
    e.stopPropagation()
    setCurrStep(benefitSteps.loading)
    let benefitId = null
    if (Array.isArray(selectedBenefit)) {
      benefitId = selectedBenefit.map(({ benefit_id: id }) => id)
    } else {
      benefitId = selectedBenefit.benefit_id
    }
    const payload = {
      benefit_id: benefitId,
      benefitId,
      application_no: applicationNo,
      questionData: addOnUserResponse,
      source: 'direct',
      insured_list: selectedTapTravelUserList,
      internal_id: internalId
    }
    if (isAgency) {
      runCreateClaim(payload, { isAgency: true })
    } else {
      runCreateClaim(payload)
    }
  }, [
    selectedBenefit,
    applicationNo,
    addOnUserResponse,
    selectedTapTravelUserList,
    internalId,
    isAgency,
    runCreateClaim
  ])

  const moveToTSIInforBanner = useCallback(() => {
    setCurrStep(benefitSteps.tsiInfoBanner)
  }, [])

  const tapTravelUserListChangeHandler = useCallback((selectedUserList) => {
    setTapTravelSelectedUserList(selectedUserList)
  }, [])

  const asdpTravelCreateClaim = useCallback((e) => {
    e.stopPropagation()
    setCurrStep(benefitSteps.loading)
    const payload = {
      benefit_id: selectedBenefit.benefit_id,
      benefitId: selectedBenefit.benefit_id,
      application_no: applicationNo,
      questionData: addOnUserResponse,
      source: 'direct',
      insured_list: selectedAsdpTravelUserList,
      internal_id: internalId,
      has_trip_cancellation_benefit: hasTripCancellationBenefit
    }
    if (isAgency) {
      runCreateClaim(payload, { isAgency: true })
    } else {
      runCreateClaim(payload)
    }
  }, [
    selectedBenefit,
    applicationNo,
    addOnUserResponse,
    selectedAsdpTravelUserList,
    internalId,
    hasTripCancellationBenefit,
    isAgency,
    runCreateClaim
  ])

  const asdpTravelUserListChangeHandler = useCallback((selectedUserList) => {
    setAsdpTravelSelectedUserList(selectedUserList)
  }, [])

  const asdpHasTripCancellationBenefitChangeHandler = useCallback((value) => {
    setHasTripCancellationBenefit(value)
    if (value) {
      setCurrStep(benefitSteps.tsiInfoBanner)
    }
  }, [])

  const nextDisabledButton = isMultiBenefitClaimable ? (selectedBenefit?.length) : !selectedBenefit

  const benefitFooter = isMobile
    ? <MobileFooterButtonWrapper>
      <MobileFooterButton onClick={closeBenefitModal} backgound={COLORS.white} color={COLORS.tapPartnerBlue}>
        <FormattedMessage id={LANG_STRINGS.cancel} />
      </MobileFooterButton>
      {Array.isArray(additionalProtection) && additionalProtection.length
          ? (
            <MobileFooterButton
              disabled={nextDisabledButton}
              onClick={onNextClickHandler}
              backgound={COLORS.tapPartnerBlue}
              color={COLORS.white}
            >
              <FormattedMessage id={LANG_STRINGS.next} />
            </MobileFooterButton>
          )
          : (
            <MobileFooterButton
              disabled={nextDisabledButton}
              onClick={onContinueClickHandler}
              backgound={COLORS.tapPartnerBlue}
              color={COLORS.white}
            >
              <FormattedMessage id={LANG_STRINGS.continue} />
            </MobileFooterButton>
          )
      }
    </MobileFooterButtonWrapper>
    : (
      <FooterWrapper>
        <NoBenefitCopyRightText>
          <FormattedMessage id={LANG_STRINGS.noBenefitCopyRight} />
        </NoBenefitCopyRightText>
        <FooterButtonWrapper>
          <FooterButton onClick={closeBenefitModal} backgound={COLORS.white} color={COLORS.tapPartnerBlue}>
            <FormattedMessage id={LANG_STRINGS.cancel} />
          </FooterButton>
          {Array.isArray(additionalProtection) && additionalProtection.length
              ? (
                <FooterButton
                  disabled={nextDisabledButton}
                  onClick={onNextClickHandler}
                  backgound={COLORS.tapPartnerBlue}
                  color={COLORS.white}
                >
                  <FormattedMessage id={LANG_STRINGS.next} />
                </FooterButton>
              )
              : (
                <FooterButton
                  disabled={nextDisabledButton}
                  onClick={onContinueClickHandler}
                  backgound={COLORS.tapPartnerBlue}
                  color={COLORS.white}
                >
                  <FormattedMessage id={LANG_STRINGS.continue} />
                </FooterButton>
              )
          }
        </FooterButtonWrapper>
      </FooterWrapper>
    )

  const asdpTravelUserListFooter = (
    <FooterWrapper>
      <FooterButtonWrapper>
        <FooterButton onClick={closeBenefitModal} backgound={COLORS.white} color={COLORS.tapPartnerBlue}>
          <FormattedMessage id={LANG_STRINGS.cancel} />
        </FooterButton>
        <FooterButton
          disabled={!selectedAsdpTravelUserList.length}
          onClick={moveToTSIInforBanner}
          backgound={COLORS.tapPartnerBlue}
          color={COLORS.white}
        >
          <FormattedMessage id={LANG_STRINGS.continue} />
        </FooterButton>
      </FooterButtonWrapper>
    </FooterWrapper>
  )

  const tapTravelUserListFooter = (
    <FooterWrapper>
      <FooterButtonWrapper>
        <FooterButton onClick={closeBenefitModal} backgound={COLORS.white} color={COLORS.tapPartnerBlue}>
          <FormattedMessage id={LANG_STRINGS.cancel} />
        </FooterButton>
        <FooterButton
          disabled={!selectedTapTravelUserList.length}
          onClick={moveToTSIInforBanner}
          backgound={COLORS.tapPartnerBlue}
          color={COLORS.white}
        >
          <FormattedMessage id={LANG_STRINGS.continue} />
        </FooterButton>
      </FooterButtonWrapper>
    </FooterWrapper>
  )

  const selectionSteps = [
    benefitSteps.loading,
    benefitSteps.singleBenefitList,
    benefitSteps.multiBenefitList,
    benefitSteps.errorBenefitMessage
  ]
  const userListSteps = [benefitSteps.asdpTravelUserList, benefitSteps.tapTravelUserList]
  const modalHeaderText = selectionSteps.includes(currStep) || !selectedBenefit
    ? <IntlMessages id={LANG_STRINGS.selectBenefitModalText} />
    : userListSteps.includes(currStep)
      ? <IntlMessages id={LANG_STRINGS.selectUserListHeader} />
      : <IntlMessages id={selectedBenefit?.benefit_name} />

  const modalBody = () => {
    switch (currStep) {
      case benefitSteps.loading:
        return (
          <CenterBodyWrapper>
            <Loader />
          </CenterBodyWrapper>
        )
      case benefitSteps.singleBenefitList:
        return (
          <div>
            <ModalBodyWrapper>
              <SingleBenefitList
                benefitList={benefitList}
                onChange={benefitListChangeHandler}
              />
              {
                isMobile &&
                <NoBenefitCopyRightText>
                  <FormattedMessage id={LANG_STRINGS.noBenefitCopyRight} />
                </NoBenefitCopyRightText>
              }
            </ModalBodyWrapper>
            {benefitFooter}
          </div>
        )
      case benefitSteps.multiBenefitList:
        return (
          <div>
            <ModalBodyWrapper>
              <MultiBenefitList
                benefitList={benefitList}
                selectedBenefit={selectedBenefit}
                onChange={multiBenefitListChangeHandler}
              />
            </ModalBodyWrapper>
            {benefitFooter}
          </div>
        )
      case benefitSteps.addOnQuestionList:
        return (
          <AddOnsContent
            handleSubmit={handleSubmit}
            handleCloseAddOns={handleCloseAddOns}
            handleQuestionsChange={handleQuestionsChange}
            totalQuestionsList={questionnaireData}
            totalQuestionsListError={totalQuestionsListError}
            questionsListLoading={questionsListLoading}
          />
        )
      case benefitSteps.validateOrCreateClaimMessage:
        return (
          <ErrorWrapper>
            <ErrorImage src={AlertRedIcon} />
            <BenefitErrorText>
              <IntlMessages id={validateClaimErrorMessage} />
            </BenefitErrorText>
            <ErrorText>
              <IntlMessages id={LANG_STRINGS.cannotSubmitClaimForBenefit} />
              <ErrorBenefitTextName >
                <IntlMessages id={selectedBenefit?.benefit_name} />
              </ErrorBenefitTextName>
            </ErrorText>
            <ErrorBenefitCustomerContact>
              <IntlMessages id={LANG_STRINGS.customerReachOutcomeDetailsBenefitText} />
            </ErrorBenefitCustomerContact>
            <ErrorCloseButton onClick={closeBenefitModal}>
              <IntlMessages id={LANG_STRINGS.close} />
            </ErrorCloseButton>
          </ErrorWrapper>
        )
      case benefitSteps.errorBenefitMessage:
        return (
          <Center>
            <BenefitErrorText>
              <IntlMessages id={getBenefitListUserMessage} />
            </BenefitErrorText>
          </Center>
        )
      case benefitSteps.tapTravelUserList:
        if (getTapTravelUserListError && tapTravelUserList.length === 0) {
          return (
            <Center>
              <BenefitErrorText>
                <IntlMessages id={getFamilyBenefitUserMessage} />
              </BenefitErrorText>
            </Center>
          )
        }
        if (tapTravelUserListLoading) {
          return (
            <Center>
              <Loader />
            </Center>
          )
        }
        return (
          <ModalBodyWrapper>
            <TapTravelUserCardList
              userList={tapTravelUserList}
              onChange={tapTravelUserListChangeHandler}
            />
            {tapTravelUserListFooter}
          </ModalBodyWrapper>
        )
      case benefitSteps.asdpTravelUserList:
        return (
          <ModalBodyWrapper>
            <AsdpTravelUserCardList
              benefitId={selectedBenefit?.benefit_id}
              applicationNo={applicationNo}
              internalId={internalId}
              onChange={asdpTravelUserListChangeHandler}
              onRemainingTSIChange={setAsdpBenefitRemainingTSI}
              onHasTripCancellationBenefitChange={asdpHasTripCancellationBenefitChangeHandler}
            />
            {asdpTravelUserListFooter}
          </ModalBodyWrapper>
        )
      case benefitSteps.tsiInfoBanner: {
        const tsiAmount = isAsdpFerryTravelPolicy ? asdpBenefitRemainingTSI : familyEligibleUserBenefitRemainingTSI
        const formattedTSI = formatCurrency(tsiAmount, 'Rp')
        return (
          <ModalBodyWrapper>
            <ErrorWrapper>
              <ErrorImage src={InfoIcon} />
              <BenefitErrorText color={COLORS.tapPartnerBlue}>
                <IntlMessages
                  id={LANG_STRINGS.totalRemainingValueLeft}
                  values={{
                    amount: formattedTSI
                  }}
                />
              </BenefitErrorText>
              <ErrorText>
                <IntlMessages id={LANG_STRINGS.pleaseNoteThatTheMaximumClaimPaymentIsForBenefits} />
                <ErrorBenefitTextName >
                  <IntlMessages id={selectedBenefit?.benefit_name} />
                </ErrorBenefitTextName>
                <IntlMessages
                  id={LANG_STRINGS.isWorthIDR}
                  values={{
                    amount: formattedTSI
                  }}
                />
              </ErrorText>
              <ErrorBenefitCustomerContact>
                <IntlMessages id={LANG_STRINGS.customerReachOutcomeDetailsBenefitText} />
              </ErrorBenefitCustomerContact>
              <ErrorCloseButton onClick={isAsdpFerryTravelPolicy ? asdpTravelCreateClaim : tapTravelCreateClaim}>
                <IntlMessages id={LANG_STRINGS.longContinueText} />
              </ErrorCloseButton>
            </ErrorWrapper>
          </ModalBodyWrapper>
        )
      }
      case benefitSteps.secondClaimOnSameBenefit:
        return (
          <SecondClaimOnSameBenefit>
            <ErrorWrapper>
              <ErrorImage src={InfoIcon} />
              <ErrorText color={COLORS.black}>
                <IntlMessages id={validateClaimErrorMessage} />
              </ErrorText>
            </ErrorWrapper>
            <FooterWrapper>
              <FooterButtonWrapper>
                <FooterButton onClick={closeBenefitModal} backgound={COLORS.white} color={COLORS.tapPartnerBlue}>
                  <FormattedMessage id={LANG_STRINGS.cancel} />
                </FooterButton>
                <FooterButton
                  onClick={createClaim}
                  backgound={COLORS.tapPartnerBlue}
                  color={COLORS.white}
                >
                  <FormattedMessage id={LANG_STRINGS.continue} />
                </FooterButton>
              </FooterButtonWrapper>
            </FooterWrapper>
          </SecondClaimOnSameBenefit>
        )
      default:
        return null
    }
  }

  return (
    isMobile
      ? <Modal
        isMobile
        width='100vw'
        closeModal={closeBenefitModal}
        headerText={modalHeaderText}
        footer={<></>}
        markupText={modalBody()}
        modalBodyStyle={{
          display: 'block',
          paddingBottom: 0,
          background: COLORS.almostWhite
        }}
        headerBackgroundColor={getAssets().headerBackgroundColor || ''}
        headerTextColor={getAssets().headerTextColor || ''}
      />
      : <Modal
        width='800px'
        closeModal={closeBenefitModal}
        headerText={modalHeaderText}
        footer={<></>}
        markupText={modalBody()}
        modalBodyStyle={{
          display: 'block',
          paddingBottom: 0,
          background: COLORS.almostWhite
        }}
        headerBackgroundColor={getAssets().headerBackgroundColor || ''}
        headerTextColor={getAssets().headerTextColor || ''}
      />
  )
}

export default BenefitList
