import { useMutation } from '@tanstack/react-query'
import claimApi from '../../axios/claim'
import agencyApi from '../../axios/agency'
import { assertApiOk, throwApiErrorFromResponse } from '../assertApiOk'

export const VALIDATE_CLAIM_KEY = 'validate-claim'
export const CREATE_CLAIM_KEY = 'create-claim'
export const FAMILY_CREATE_CLAIM_KEY = 'family-create-claim'

const validateClaimResponse = (res) => {
  if (res?.status === 200) {
    return res.data
  }
  throwApiErrorFromResponse(res)
}

export const useValidateClaimMutation = () =>
  useMutation({
    mutationKey: [VALIDATE_CLAIM_KEY],
    mutationFn: async ({ isAgency, ...payload }) => {
      if (isAgency) {
        const query = `benefit_id=${payload.benefit_id}&internal_id=${payload.internal_id}`
        const res = await agencyApi.validateAgentClaim({ query })
        return validateClaimResponse(res)
      }
      const res = await claimApi.validateClaimUrl({ payload })
      return validateClaimResponse(res)
    }
  })

export const useCreateClaimMutation = () =>
  useMutation({
    mutationKey: [CREATE_CLAIM_KEY],
    mutationFn: async ({ isAgency, ...payload }) => {
      if (isAgency) {
        const res = await agencyApi.createAgencyClaim({ payload })
        const data = assertApiOk(res, [201])
        return data.claim_id
      }
      const res = await claimApi.postClaim({ payload })
      const data = assertApiOk(res, [201])
      return data.claim_id
    }
  })

export const useFamilyCreateClaimMutation = () =>
  useMutation({
    mutationKey: [FAMILY_CREATE_CLAIM_KEY],
    mutationFn: async (payload) => {
      const res = await claimApi.postFamilyCreateClaims(payload)
      const data = assertApiOk(res, [200, 201])
      return data.claim_id
    }
  })
