import { useEffect, useState } from 'react'
import { LANG_STRINGS } from '../../constants/lang'
import TapTravelUserCard from '../TapTravelUserCard'
import { TapTravelUserListContainer } from './tapTravelUserList.style'
import moment from 'moment'

function TapTravelUserCardList ({
  userList,
  onChange = () => { }
}) {
  const [selectedUserList, setSelectedUserList] = useState([])

  const onChangeHandler = (e, { name, participantNo }) => {
    const checked = e.target.checked
    let newUserList = [...selectedUserList]
    if (checked) {
      newUserList.push({ name, participant_number: participantNo })
    } else {
      newUserList = newUserList.filter(({ participant_number: no }) => participantNo !== no)
    }
    setSelectedUserList(newUserList)
  }

  useEffect(() => {
    onChange(selectedUserList)
  }, [
    onChange,
    selectedUserList
  ])

  return (
    <TapTravelUserListContainer>
      {
        userList?.map((user) => {
          const {
            name,
            dob,
            is_eligible: enabled,
            participant_number: participantNo,
            date_of_birth: dateOfBirth
          } = user
          const formattedDate = moment(dob || dateOfBirth).format('DD/MM/YYYY')
          const userDetails = [
            {
              key: LANG_STRINGS.dateOfBirthShort,
              value: formattedDate
            }
          ]
          const disabledText = enabled ? '' : LANG_STRINGS.individualAmountTapTravelExceededCopyRight
          return (
            <TapTravelUserCard
              key={name}
              userTitle={name}
              enabled={enabled}
              onChange={(e) => onChangeHandler(e, { name, participantNo })}
              disabledText={disabledText}
              userDetails={userDetails}
            />
          )
        })
      }
    </TapTravelUserListContainer>
  )
}

export default TapTravelUserCardList
