import { notification } from 'antd'

export const GENERAL_API_ERROR_MESSAGE = 'Terjadi kesalahan. Silakan coba lagi.'

const isGenericErrorText = (text) => {
  if (!text || typeof text !== 'string' || !text.trim()) {
    return true
  }
  if (text === 'error' || text === 'Network error') {
    return true
  }
  return /^Request failed \(\d+\)$/.test(text)
}

export const getApiErrorMessage = (err) => {
  if (!err) {
    return GENERAL_API_ERROR_MESSAGE
  }
  if (typeof err === 'string') {
    return isGenericErrorText(err) ? GENERAL_API_ERROR_MESSAGE : err
  }
  const message = err.message || ''
  return isGenericErrorText(message) ? GENERAL_API_ERROR_MESSAGE : message
}

export const showApiError = (err, intl) => {
  const raw = getApiErrorMessage(err)
  const message = intl
    ? intl.formatMessage({ id: raw, defaultMessage: raw })
    : raw

  notification.error({
    message,
    description: ''
  })
}
