import { useQuery } from '@tanstack/react-query'
import claimApi from '../../axios/claim'
import { assertApiOk } from '../assertApiOk'

export const FAMILY_ELIGIBLE_USERS_KEY = 'family-eligible-users'

export const useFamilyEligibleUserList = ({ benefit_id, application_no, internal_id }, options = {}) =>
  useQuery({
    queryKey: [FAMILY_ELIGIBLE_USERS_KEY, benefit_id, application_no, internal_id],
    queryFn: async () => {
      const res = await claimApi.getFamilyEligibleUserList({
        benefit_id,
        application_no,
        internal_id
      })
      const data = assertApiOk(res, [200, 201])
      return {
        userList: data.data?.users || [],
        benefitRemainingTSI: data?.data?.benefit_remaining_TSI || 0
      }
    },
    enabled: !!(benefit_id && application_no),
    ...options
  })
